// World data: heightmap + maps generated by tools/blender/world_gen.py, with fast CPU queries.
import * as THREE from 'three';
import { WORLD_HALF, WORLD_SIZE } from '../core/globals.js';

export const BIOME = { OCEAN: 0, MEADOW: 1, FOREST: 2, SWAMP: 3, MOUNTAIN: 4, ASH: 5, CITADEL: 6, BEACH: 7 };
export const BIOME_KEYS = ['ocean', 'meadow', 'forest', 'swamp', 'mountain', 'ash', 'citadel', 'beach'];
export const SURFACES = ['grass', 'dirt', 'stone', 'sand', 'snow', 'grass', 'mud', 'ash'];   // per splat layer

function loadImage(url) {
  return new Promise((res, rej) => {
    const im = new Image();
    im.onload = () => res(im);
    im.onerror = () => rej(new Error('image ' + url));
    im.src = url;
  });
}

function mapTexture(img, srgb = false, mips = true) {
  const t = new THREE.Texture(img);
  t.flipY = false;
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
  t.minFilter = mips ? THREE.LinearMipmapLinearFilter : THREE.LinearFilter;
  t.magFilter = THREE.LinearFilter;
  t.generateMipmaps = mips;
  t.needsUpdate = true;
  return t;
}

export class WorldData {
  async load(progress = () => {}) {
    const base = 'assets/world/';
    const [json, hbuf, cpu, splat0, splat1, nrm, tint, veg, map] = await Promise.all([
      fetch(base + 'world.json').then(r => r.json()),
      fetch(base + 'height.bin').then(r => r.arrayBuffer()),
      fetch(base + 'cpu_maps.bin').then(r => r.arrayBuffer()),
      loadImage(base + 'splat0.png'), loadImage(base + 'splat1.png'), loadImage(base + 'terrain_nrm.png'),
      loadImage(base + 'tint.png'), loadImage(base + 'veg.png'), loadImage(base + 'map.png'),
    ]);
    progress(0.6);
    this.json = json;
    this.n = json.n;
    this.cell = json.cell;
    this.hmin = json.heightMin;
    this.hscale = (json.heightMax - json.heightMin) / 65535;
    this.hq = new Uint16Array(hbuf);
    this.pois = json.pois;
    this.shrines = json.shrines;
    this.roads = json.roads;
    this.river = json.river;
    this.bridges = json.bridges;
    this.citadel = json.citadel;
    this.mapImage = map;

    // GPU textures
    const ht = new THREE.DataTexture(this.hq, this.n, this.n, THREE.RedIntegerFormat, THREE.UnsignedShortType);
    ht.internalFormat = 'R16UI';
    ht.minFilter = ht.magFilter = THREE.NearestFilter;
    ht.generateMipmaps = false;
    ht.unpackAlignment = 2;
    ht.needsUpdate = true;
    this.heightTex = ht;
    this.heightInfo = new THREE.Vector4(this.hmin, this.hscale, this.cell, this.n);
    this.splat0Tex = mapTexture(splat0);
    this.splat1Tex = mapTexture(splat1);
    this.nrmTex = mapTexture(nrm);
    this.tintTex = mapTexture(tint, false, false);
    this.vegTex = mapTexture(veg, false, false);

    // CPU copies (raw file: a canvas readback would premultiply alpha)
    const u8 = new Uint8Array(cpu);
    let o = 0;
    this.vegN = 1024; this.vegData = u8.subarray(o, o += 1024 * 1024 * 4);
    this.biomeN = 1024; this.biomeData = u8.subarray(o, o += 1024 * 1024);
    this.splatN = 512; this.surfData = u8.subarray(o, o += 512 * 512);
    this.dirtData = u8.subarray(o, o += 512 * 512);
    this.rockData = u8.subarray(o, o += 512 * 512);
    this._buildMinMax();
    progress(1);
    return this;
  }

  /** min/max height pyramid for terrain LOD culling: level 0 = 40 m leaves (16 cells). */
  _buildMinMax() {
    const n = this.n, leaf = 16, m = n / leaf;
    let mins = new Float32Array(m * m), maxs = new Float32Array(m * m);
    const hq = this.hq;
    for (let j = 0; j < m; j++) for (let i = 0; i < m; i++) {
      let lo = 65535, hi = 0;
      const j1 = Math.min((j + 1) * leaf + 1, n), i1 = Math.min((i + 1) * leaf + 1, n);
      for (let y = j * leaf; y < j1; y++) {
        const row = y * n;
        for (let x = i * leaf; x < i1; x++) { const v = hq[row + x]; if (v < lo) lo = v; if (v > hi) hi = v; }
      }
      mins[j * m + i] = lo * this.hscale + this.hmin;
      maxs[j * m + i] = hi * this.hscale + this.hmin;
    }
    this.mm = [{ n: m, min: mins, max: maxs }];
    let cur = m;
    while (cur > 1) {
      const h = cur / 2, a = new Float32Array(h * h), b = new Float32Array(h * h);
      for (let j = 0; j < h; j++) for (let i = 0; i < h; i++) {
        const k = (j * 2) * cur + i * 2;
        a[j * h + i] = Math.min(mins[k], mins[k + 1], mins[k + cur], mins[k + cur + 1]);
        b[j * h + i] = Math.max(maxs[k], maxs[k + 1], maxs[k + cur], maxs[k + cur + 1]);
      }
      this.mm.push({ n: h, min: a, max: b });
      mins = a; maxs = b; cur = h;
    }
  }

  /** Terrain height (m) at world x,z — bilinear, identical to the vertex shader. */
  height(x, z) {
    const n = this.n;
    let fx = (x + WORLD_HALF) / this.cell, fz = (z + WORLD_HALF) / this.cell;
    if (fx < 0) fx = 0; else if (fx > n - 1.001) fx = n - 1.001;
    if (fz < 0) fz = 0; else if (fz > n - 1.001) fz = n - 1.001;
    const i = fx | 0, j = fz | 0, u = fx - i, v = fz - j, k = j * n + i, hq = this.hq;
    const a = hq[k] + (hq[k + 1] - hq[k]) * u;
    const b = hq[k + n] + (hq[k + n + 1] - hq[k + n]) * u;
    return (a + (b - a) * v) * this.hscale + this.hmin;
  }

  /** Surface normal (unit) into `out` (THREE.Vector3). */
  normal(x, z, out) {
    const e = 1.25;
    const hx = this.height(x + e, z) - this.height(x - e, z);
    const hz = this.height(x, z + e) - this.height(x, z - e);
    return out.set(-hx, 2 * e, -hz).normalize();
  }

  /** Slope in degrees. */
  slope(x, z) {
    const e = 1.25;
    const hx = (this.height(x + e, z) - this.height(x - e, z)) / (2 * e);
    const hz = (this.height(x, z + e) - this.height(x, z - e)) / (2 * e);
    return Math.atan(Math.hypot(hx, hz)) * 57.29578;
  }

  _idx(x, z, n) {
    let i = ((x + WORLD_HALF) / WORLD_SIZE * n) | 0, j = ((z + WORLD_HALF) / WORLD_SIZE * n) | 0;
    if (i < 0) i = 0; else if (i >= n) i = n - 1;
    if (j < 0) j = 0; else if (j >= n) j = n - 1;
    return j * n + i;
  }

  biome(x, z) { return this.biomeData[this._idx(x, z, this.biomeN)]; }

  /** vegetation channel 0..1: c = 0 trees, 1 conifer fraction, 2 grass, 3 dead fraction */
  veg(x, z, c) { return this.vegData[this._idx(x, z, this.vegN) * 4 + c] / 255; }

  /** dominant ground layer index 0..7 (grass, dirt, rock, sand, snow, forest, mud, ash) */
  surfaceLayer(x, z) { return this.surfData[this._idx(x, z, this.splatN)]; }

  surface(x, z) { return SURFACES[this.surfaceLayer(x, z)]; }

  /** weight 0..1 of the dirt (1) or rock (2) layer */
  splatWeight(x, z, layer) {
    const k = this._idx(x, z, this.splatN);
    return (layer === 1 ? this.dirtData[k] : layer === 2 ? this.rockData[k] : 0) / 255;
  }

  inBounds(x, z, margin = 0) {
    return Math.abs(x) < WORLD_HALF - margin && Math.abs(z) < WORLD_HALF - margin;
  }
}
